"""Ledger parsing, aggregation, filtering and formatting."""

import datetime
import decimal
import re
from dataclasses import dataclass
from decimal import Decimal
from typing import Dict, Iterable, List, Optional

_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")
_AMOUNT_RE = re.compile(r"[+-]?[0-9]+(\.[0-9]{1,2})?")
_LINE_RE = re.compile(r"([^ \t]+)[ \t]+([^ \t]+)[ \t]+([^ \t]+)(?:[ \t]+(.*))?", re.DOTALL)

_CENT = Decimal("0.01")


@dataclass(frozen=True)
class Entry:
    date: datetime.date
    category: str
    amount: Decimal
    note: str = ""


class ParseError(ValueError):
    """A line of the ledger is a mistake. ``line`` is its 1-based number."""

    def __init__(self, line: int, reason: str):
        super().__init__("line %d: %s" % (line, reason))
        self.line = line
        self.reason = reason


def parse_date(text: str) -> datetime.date:
    """Parse ``YYYY-MM-DD`` strictly; raise ``ValueError`` if not a real date."""
    if not _DATE_RE.fullmatch(text):
        raise ValueError("invalid date %r" % text)
    try:
        return datetime.date(int(text[:4]), int(text[5:7]), int(text[8:10]))
    except ValueError:
        raise ValueError("invalid date %r" % text) from None


def parse(text: str) -> List[Entry]:
    """Parse ledger text into entries, in file order."""
    entries = []
    for number, raw in enumerate(text.splitlines(), start=1):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        match = _LINE_RE.fullmatch(line)
        if match is None:
            raise ParseError(number, "expected DATE CATEGORY AMOUNT [NOTE], got %r" % line)
        date_text, category, amount_text, note = match.groups()
        try:
            date = parse_date(date_text)
        except ValueError as exc:
            raise ParseError(number, str(exc)) from None
        if not _AMOUNT_RE.fullmatch(amount_text):
            raise ParseError(number, "invalid amount %r" % amount_text)
        entries.append(
            Entry(date, category.lower(), Decimal(amount_text), (note or "").strip())
        )
    return entries


def _sum(amounts: Iterable[Decimal]) -> Decimal:
    # Exact addition: the default 28-digit context would round huge amounts.
    with decimal.localcontext() as ctx:
        ctx.prec = 1000
        total = Decimal(0)
        for amount in amounts:
            total += amount
        return total


def balance(entries: Iterable[Entry]) -> Decimal:
    return _sum(e.amount for e in entries)


def _group(entries: Iterable[Entry], key) -> Dict[str, Decimal]:
    groups: Dict[str, List[Decimal]] = {}
    for entry in entries:
        groups.setdefault(key(entry), []).append(entry.amount)
    return {name: _sum(groups[name]) for name in sorted(groups)}


def by_category(entries: Iterable[Entry]) -> Dict[str, Decimal]:
    return _group(entries, lambda e: e.category)


def by_month(entries: Iterable[Entry]) -> Dict[str, Decimal]:
    return _group(entries, lambda e: "%04d-%02d" % (e.date.year, e.date.month))


def filter_entries(
    entries: Iterable[Entry],
    category: Optional[str] = None,
    since: Optional[datetime.date] = None,
    until: Optional[datetime.date] = None,
) -> List[Entry]:
    wanted = category.lower() if category is not None else None
    result = []
    for entry in entries:
        if wanted is not None and entry.category != wanted:
            continue
        if since is not None and entry.date < since:
            continue
        if until is not None and entry.date > until:
            continue
        result.append(entry)
    return result


def format_money(amount: Decimal) -> str:
    """Render with exactly two decimals; zero is always ``0.00``."""
    if amount == 0:
        return "0.00"
    with decimal.localcontext() as ctx:
        ctx.prec = len(amount.as_tuple().digits) + 4
        return str(amount.quantize(_CENT))


def format_entry(entry: Entry) -> str:
    """``YYYY-MM-DD category AMOUNT[ NOTE]``."""
    line = "%s %s %s" % (entry.date.isoformat(), entry.category, format_money(entry.amount))
    if entry.note:
        line += " " + entry.note
    return line
"""Command line interface: ``pennywise``."""

import argparse
import csv
import datetime
import io
import json
import sys
from typing import List, Optional

from . import ledger

EXIT_OK = 0
EXIT_LEDGER = 1
EXIT_USAGE = 2


class _Fail(Exception):
    """Abort the command with an exit status and a stderr message."""

    def __init__(self, status: int, message: str):
        super().__init__(message)
        self.status = status
        self.message = message


def _date_arg(text: str) -> datetime.date:
    try:
        return ledger.parse_date(text)
    except ValueError:
        raise argparse.ArgumentTypeError(
            "invalid date %r (expected a real date as YYYY-MM-DD)" % text
        ) from None


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="pennywise", description="Report where the money in a plain-text ledger went."
    )
    sub = parser.add_subparsers(dest="command", metavar="COMMAND")
    sub.required = True

    p = sub.add_parser("balance", help="print the total of all entries")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("summary", help="print totals per category or month")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--by", choices=["category", "month"], default="category")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("list", help="print entries, oldest first")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--category", help="only this category (case-insensitive)")
    p.add_argument("--since", type=_date_arg, metavar="DATE", help="from DATE, inclusive")
    p.add_argument("--until", type=_date_arg, metavar="DATE", help="to DATE, inclusive")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("add", help="append an entry to a ledger file")
    p.add_argument("file", metavar="FILE", help="ledger file (created if missing)")
    p.add_argument("date", metavar="DATE")
    p.add_argument("category", metavar="CATEGORY")
    p.add_argument("amount", metavar="AMOUNT")
    p.add_argument("note", metavar="NOTE", nargs="?", default="")

    p = sub.add_parser("export", help="print entries as CSV")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--format", choices=["csv"], default="csv")

    return parser


def _read_text(name: str) -> str:
    try:
        if name == "-":
            stream = sys.stdin
            raw = stream.buffer.read() if hasattr(stream, "buffer") else stream.read()
            return raw.decode("utf-8") if isinstance(raw, bytes) else raw
        with open(name, "rb") as handle:
            return handle.read().decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _Fail(EXIT_USAGE, "%s: not valid UTF-8 (%s)" % (_label(name), exc.reason)) from None
    except OSError as exc:
        raise _Fail(EXIT_USAGE, "%s: %s" % (_label(name), exc.strerror or exc)) from None


def _label(name: str) -> str:
    return "<stdin>" if name == "-" else name


def _load(name: str) -> List[ledger.Entry]:
    text = _read_text(name)
    try:
        return ledger.parse(text)
    except ledger.ParseError as exc:
        raise _Fail(EXIT_LEDGER, "%s: %s" % (_label(name), exc)) from None


def _ordered(entries: List[ledger.Entry]) -> List[ledger.Entry]:
    return sorted(entries, key=lambda e: e.date)  # stable: same day keeps file order


def _cmd_balance(args) -> str:
    total = ledger.format_money(ledger.balance(_load(args.file)))
    if args.json:
        return json.dumps({"balance": total}) + "\n"
    return total + "\n"


def _cmd_summary(args) -> str:
    entries = _load(args.file)
    groups = ledger.by_month(entries) if args.by == "month" else ledger.by_category(entries)
    groups = {name: ledger.format_money(groups[name]) for name in sorted(groups)}
    if args.json:
        return json.dumps(groups) + "\n"
    return "".join("%s  %s\n" % item for item in groups.items())


def _cmd_list(args) -> str:
    entries = _ordered(_load(args.file))
    entries = ledger.filter_entries(entries, args.category, args.since, args.until)
    if args.json:
        return json.dumps(
            [
                {
                    "date": e.date.isoformat(),
                    "category": e.category,
                    "amount": ledger.format_money(e.amount),
                    "note": e.note,
                }
                for e in entries
            ]
        ) + "\n"
    return "".join(ledger.format_entry(e) + "\n" for e in entries)


def _cmd_export(args) -> str:
    entries = _ordered(_load(args.file))
    out = io.StringIO()
    writer = csv.writer(out, lineterminator="\n")
    writer.writerow(["date", "category", "amount", "note"])
    for e in entries:
        writer.writerow([e.date.isoformat(), e.category, ledger.format_money(e.amount), e.note])
    return out.getvalue()


def _cmd_add(args) -> str:
    fields = (args.date, args.category, args.amount)
    line = " ".join(fields + ((args.note,) if args.note else ()))
    rejected = "entry %r" % line

    def reject(reason: str) -> _Fail:
        return _Fail(EXIT_LEDGER, "%s: %s" % (rejected, reason))

    if any(not f or any(c in " \t" for c in f) for f in fields):
        raise reject("date, category and amount must each be a single word")
    if line.splitlines() != [line]:
        raise reject("note must not contain a line break")
    try:
        (entry,) = ledger.parse(line)
    except ledger.ParseError as exc:
        raise reject(str(exc)) from None
    except ValueError:
        raise reject("not a ledger entry") from None
    text = ledger.format_entry(entry)

    try:
        try:
            with open(args.file, "rb") as handle:
                existing = handle.read()
        except FileNotFoundError:
            existing = b""
        prefix = b"\n" if existing and not existing.endswith((b"\n", b"\r")) else b""
        with open(args.file, "ab") as handle:
            handle.write(prefix + (text + "\n").encode("utf-8"))
    except OSError as exc:
        raise _Fail(EXIT_USAGE, "%s: %s" % (args.file, exc.strerror or exc)) from None
    return text + "\n"


_COMMANDS = {
    "balance": _cmd_balance,
    "summary": _cmd_summary,
    "list": _cmd_list,
    "add": _cmd_add,
    "export": _cmd_export,
}


def main(argv: Optional[List[str]] = None) -> int:
    try:
        args = _build_parser().parse_args(argv)
    except SystemExit as exc:  # argparse: 0 for --help, 2 for a bad command line
        code = exc.code
        return code if isinstance(code, int) else EXIT_USAGE
    try:
        output = _COMMANDS[args.command](args)
    except _Fail as fail:
        sys.stderr.write("pennywise: %s\n" % fail.message)
        return fail.status
    sys.stdout.write(output)
    return EXIT_OK


if __name__ == "__main__":
    sys.exit(main())
