import os
import unittest

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))


class PackagingTests(unittest.TestCase):
    def setUp(self):
        with open(os.path.join(ROOT, "pyproject.toml"), encoding="utf-8") as handle:
            self.text = handle.read()

    def test_console_script(self):
        self.assertRegex(self.text, r'(?m)^pennywise\s*=\s*"pennywise\.cli:main"')

    def test_python_version_and_no_dependencies(self):
        self.assertRegex(self.text, r'(?m)^requires-python\s*=\s*">=3\.9"')
        self.assertRegex(self.text, r"(?m)^dependencies\s*=\s*\[\s*\]")

    def test_public_api(self):
        import _src  # noqa: F401
        import pennywise

        for name in ("parse", "ParseError", "balance", "by_category", "by_month", "filter_entries", "Entry"):
            self.assertTrue(hasattr(pennywise, name), name)


if __name__ == "__main__":
    unittest.main()

